CssValueDef cssMathFunction(PrCssKeyword keyword) {
    switch (keyword) {
    case PrCssKeyword_Calc:     return CssValueDef_CalcFn;
    case PrCssKeyword_Min:      return CssValueDef_MinFn;
    case PrCssKeyword_Max:      return CssValueDef_MaxFn;
    case PrCssKeyword_Clamp:    return CssValueDef_ClampFn;
    case PrCssKeyword_Round:    return CssValueDef_RoundFn;
    case PrCssKeyword_Mod:      return CssValueDef_ModFn;
    case PrCssKeyword_Rem:      return CssValueDef_RemFn;
    case PrCssKeyword_Sin:      return CssValueDef_SinFn;
    case PrCssKeyword_Cos:      return CssValueDef_CosFn;
    case PrCssKeyword_Tan:      return CssValueDef_TanFn;
    case PrCssKeyword_Asin:     return CssValueDef_AsinFn;
    case PrCssKeyword_Acos:     return CssValueDef_AcosFn;
    case PrCssKeyword_Atan:     return CssValueDef_AtanFn;
    case PrCssKeyword_Atan2:    return CssValueDef_Atan2Fn;
    case PrCssKeyword_Pow:      return CssValueDef_PowFn;
    case PrCssKeyword_Sqrt:     return CssValueDef_SqrtFn;
    case PrCssKeyword_Hypot:    return CssValueDef_HypotFn;
    case PrCssKeyword_Log:      return CssValueDef_LogFn;
    case PrCssKeyword_Exp:      return CssValueDef_ExpFn;
    case PrCssKeyword_Abs:      return CssValueDef_AbsFn;
    case PrCssKeyword_Sign:     return CssValueDef_SignFn;
    case PrCssKeyword_Progress: return CssValueDef_ProgressFn;
    case PrCssKeyword_Random:   return CssValueDef_RandomFn;
    default:
        return CssValueDef_Count;
    }
}

CssValueDef cssWholeValueFunction(PrCssKeyword keyword) {
    switch (keyword) {
    case PrCssKeyword_Cycle:       return CssValueDef_CycleFn;
    case PrCssKeyword_FirstValid:  return CssValueDef_FirstValidFn;
    case PrCssKeyword_Interpolate: return CssValueDef_InterpolateFn;
    default:
        return CssValueDef_Count;
    }
}

CssValueDef cssSubstitutionFunction(PrCssKeyword keyword) {
    switch (keyword) {
    case PrCssKeyword_Var:        return CssValueDef_VarArgs;
    case PrCssKeyword_Attr:       return CssValueDef_AttrArgs;
    case PrCssKeyword_Env:        return CssValueDef_EnvArgs;
    case PrCssKeyword_If:         return CssValueDef_IfArgs;
    case PrCssKeyword_Inherit:    return CssValueDef_InheritArgs;
    case PrCssKeyword_Ident:      return CssValueDef_IdentArgs;
    case PrCssKeyword_RandomItem: return CssValueDef_RandomItemArgs;
    default:
        return CssValueDef_Count;
    }
}

